def audit_sealed_scope(doc,mapping,seal,load,require):
    for k,n in dict(actual_objects=13,actual_pages=13,actual_complete_body_holds=51,actual_complete_name_holds=51,offline_only_objects=0).items():require(doc[k]==n,'manuscript coverage:'+k)
    require(doc['offline_only_object_IDs']==[] and not doc['full_goal_complete'] and all(doc[k] for k in ['full207_name_role_alias_andearlier_review_open','source_middle_field_not_invented_surname_rank_or_nationality','Samwell_full_catalogue_middle_unapproved_andbroader_review_open','reported_armadillo_shield_Africa_clue_personal_remembrance_andluck_condition_preserved','no_modern_date_new_rank_relationship_orconfirmed_item_outcome_invented']),'remaining objective andsource factual scope')
    for r in doc['records']:
        require(r['speaker']=={2:'Lil Argot',22:'Samwell Khan'}[r['source_selector']],'source personal name')
        require(all(isinstance(r[k],str) and r[k].strip() for k in ['context','source_meaning','localization_note','editorial_finding']),'individual contextual reasoning')
        require(r['no_manual_line_break_padding_or_alignment_authored'] and r['original_physical_native_rows_per_page']==r['native_profile_maximum_total_rows']==4 and r['native_page_count']==1,'authored prose andoriginal geometry')
    approval=load(doc['native_approval'])
    for k,n in dict(revision_count=6,retention_count=7,native_pages=13,logical_compiled_alignments=104,stored_alignments=52,zero_ink_parity_tails=6,name_alignments=32,layout_rejections=62,actual_objects=13,complete_body_holds=51,complete_name_holds=51,offline_only_objects=0).items():require(approval[k]==n,'native approval:'+k)
    f,s,q=[load(doc[k]) for k in ['native_font_proof','native_stored_proof','native_policy_validation']]
    require(f['complete_native_pages']==13 and f['logical_compiled_input_alignment_cases']==104 and all(f[k] for k in ['all13_single_original_four_row_pages','all13_complete_prose_paragraphs','all_first_internal_final_visible_glyphs_in_order_unique_cells_and_bounds','each216x64_plane_exact_independent_current_font_and_all_canaries','all_original_current_font_renderer_instructions_verified','original_pair_phase_and_guards_bound_without_new_substitutions','zero_source_and_compiled_FI_FA_FO_no_substitutions_added','only_original_static_selectors2_22']),'complete font proof')
    require(s['stored_alignment_cases']==52 and s['fresh_alignment_cases']==24 and s['exact_reused_alignment_cases']==28 and s['zero_ink_parity_tail_count']==6 and s['complete_native_pages']==13 and s['all_final_stored_targets_equal_reviewed_complete_native_ink'] and s['all_bounds_canaries_pair_phase_and_zero_macros_pass'],'complete stored proof')
    require(q['positive_paragraph_count']==13 and q['negative_count']==len(q['negative_cases'])==62 and all(c['rejected'] for c in q['negative_cases']) and len(q['row_count_reasons'])==5 and q['all_base_QA_diagnostics_preserved_zero_warning_waivers'],'policy obligations')
    require(sum(bool(r['row_count_reason']) for r in doc['records'])==5 and not any(r['exact_reviewed_base_warnings'] or r['qa_waivers'] or r['qa_waiver_reason'] for r in doc['records']),'five exact row reasons andzero warnings orwaivers')
    names=load(doc['speaker_name_review']);require(all(names[k] for k in ['both_actual_final_English_personal_names_complete','two_contextual_progressive_names_retained_no_assets_or_duplicate_credit','source_middle_field_not_invented_surname_rank_or_nationality','Samwell_full_catalogue_untranslated_middle_unapproved_andbroader_consumer_review_open','Samwell_full_catalogue_middle_unapproved_andnot_changed','progressive_headers_only_not_full_catalogue_wording_approval','full207_name_role_alias_andearlier_name_review_open','no_new_name_or_dialogue_credit']),'name consumers andscope')
    source=NdsImage.open(doc['source_ROM']).read_file('/__arm9__.bin');current=NdsImage.open(doc['current_ROM']).read_file('/__arm9__.bin')
    require(sha(source)=='0d1541022ef95afe02ad7a1a381a1fc3e5e74442a5f0408f436d68a5d306d731','clean name/item runtime')
    require(sha(current)==doc['current_ARM9_sha256'],'current name/item runtime')
    def fields(row):
        if row.get('source_null'):require(row['current_null'],'null middle preserved');return
        p=row['pointer_field'];require(int.from_bytes(source[p:p+4],'little')==row['source_pointer'] and int.from_bytes(current[p:p+4],'little')==row['current_pointer'],'exact name/item pointers')
        for arm,which in [(source,'source'),(current,'current')]:
            at=row[which+'_storage_offset'];raw=bytes.fromhex(row[which+'_terminated_hex']);require(arm[at:at+len(raw)]==raw and raw[-1]==0 and 0 not in raw[:-1],'exact terminated name/item field')
    for n in names['records']:
        actor=n['actor_ID'];require(n['english']=={2:'Lil Argot',22:'Samwell Khan'}[actor] and [r['Japanese'] for r in n['source_fields'] if r.get('Japanese')]=={2:['リル','アーゴット'],22:['サムウェル','カーン','ダ']}[actor],'exact source personal fields')
        require(n['catalogue_current']=={2:'Lil Argot',22:'Samwell ダ Khan'}[actor] and n['catalogue_wording_editorially_approved']==(actor==2) and n['actual_final_English_header_observed'] and n['full_catalogue_UI_unvisited'] and n['no_name_asset_or_duplicate_credit'],'progressive-only approval;catalogue middle unapproved')
        for r in n['source_fields']:fields(r)
    getters=load(doc['current_consumer_proof'])['native_four_distinct_name_consumers']['rows'];require({(r['actor_ID'],r['consumer']):r['text'] for r in getters}=={(2,'progressive-nameplate'):'Lil Argot',(2,'full-catalogue'):'Lil Argot',(22,'progressive-nameplate'):'Samwell Khan',(22,'full-catalogue'):'Samwell ダ Khan'},'four exact name getters')
    item=load(doc['source_named_item_binding']);require(all(item[k] for k in ['Samwell_mixed_Japanese_full_catalogue_wording_not_editorially_approved','candidate_spelling_not_shipped_or_globally_approved','source_named_shield_not_runtime_FI_substitution','current_Armadillo_Hide_asset_andharder_than_iron_source_meaning_bound','no_item_or_actor_asset_change_or_duplicate_credit','no_inventory_card_orcomplete_item_mechanic_approval','full207_name_role_alias_andSamwell_middle_consumer_review_remains_open']),'item/name binding scope')
    r=item['source_named_item'];require((r['record_ID'],r['Japanese'],r['English'],r['source_terminated_hex'],r['current_terminated_hex'])==('DK4_ITEM_POINTER_050','アルマジロの鉄皮','Armadillo Hide','8341838b837d8357838d82cc935394e700','41726d6164696c6c6f204869646500'),'exact named shield');fields(r)
    middle=item['Samwell_middle_field'];require(middle==next(n for n in names['records'] if n['actor_ID']==22)['source_fields'][2] and middle['Japanese']==middle['current_English']=='ダ' and middle['source_terminated_hex']==middle['current_terminated_hex']=='835f00','unapproved source middle retained exactly')
    a,l=load(doc['actual_English_proof']),load(doc['later_scope_proof']);o=mapping['observed_comparison_contract']
    measured=dict(source_exit=a['source_exit_frame'],English_exit=a['exit_frame'],normal_port=a['normal_port_sample_frame'],body_holds=a['actual_complete_body_holds'],name_holds=a['actual_complete_name_holds'],command_difference_rows=len(a['command_comparison_differences']),duration_changes=len(a['command_duration_changes']),later_samples=len(a['later_sampled_whole_frame_comparisons']),later_RGB_differences=len(l['later_sampled_RGB_differences']),component_equality=l['five_native_component_equality'],captains=l['captain_IDs'],PRNG_seeds=l['final_PRNG_seeds'],following_B120_ends=[r['B120_end_frames'] for r in l['following_B120']])
    require(measured==o==seal['observed_comparison_contract'],'all actual measured comparisons preserved')
    require(o==dict(source_exit=5973,English_exit=5973,normal_port=6070,body_holds=51,name_holds=51,command_difference_rows=0,duration_changes=0,later_samples=167,later_RGB_differences=0,component_equality=dict(state=True,models=True,persistent_objects=True,tasks=True,calendar=True),captains=[2,2],PRNG_seeds=[894298431,894298431],following_B120_ends=[[10774],[10774]]),'approved measured comparison')
    require(a['actual_native_pages']==len(a['actual_page_panels'])==13 and not a['incomplete_sampled_body_holds'] and len(a['semantic_upper_portrait_pairs'])==13 and not a['page_transitions'] and all(a[k] for k in ['all13_single_original_native_pages_verified','initialized_B22_not_natural_event228_original_location_earned_progress_full_effects_route_orhardware','no_roles_roster_funds_conditions_RNG_results_RAM_code_battery_or_savestate_forced','no_full_RAM_every_intermediate_frame_future_sequence_broad_simulation_orcausal_claim','full207_name_role_alias_andearlier_editorial_scope_open','both_source_personal_names_preserved','all_following_resident_payloads_verified_against_actual_SC0_to_SC3_bank','Samwell_mixed_Japanese_full_catalogue_middle_unapproved','progressive_header_approval_only_no_name_asset_change']),'actual pages andcoverage limits')
    plan=load(next(p for p in a['evidence'] if Path(p).name=='run_plan.json'));fixture=load(a['fixture']);require(plan['source_event228_not_naturally_selected'] and plan['displayed_original_source_block']==228 and fixture['fixtures'][0]['source_block']==228 and fixture['initialized_Amsterdam_B22_not_natural_event228_location_or_earned_progress'],'actual B228 entry scope')
    for p in a['actual_page_panels']:require(p['complete_body_holds'] and all(h['complete_independent_native_body_black_gray_all_glyphs_equal'] for h in p['complete_body_holds']),'every actual page complete')
    for p in a['actual_panels']:require(p['native_pages']==1 and {h['native_page'] for h in p['complete_body_holds']}=={1} and {h['native_page'] for h in p['complete_name_holds']}=={1},'every body andname page held')
    c=load(doc['relocated_control_proof']);require(all(c[k] for k in ['all13_complete_preambles_voices_andzero_macro_bodies_bound','zero_original_orinvented_FI_FA_FO','normal_state0_retains_existing_value_word_in_all25_cases','original_normal_end740_four_bytes_andtarget_no_tail_preserved','all15_commands_no_predicate_relative_typed_style_orpicture_assumptions','opaque_A000_effects_bridged_not_fully_explained']),'control boundary scope')
    require(c['source_A000']['source_command_hex']=='00a0ffff32000110' and c['source_A000']['rows']==c['relocated_A000']['rows'] and c['source_A000']['opaque_effect_bridges']==c['relocated_A000']['opaque_effect_bridges'],'effect structural consumer')
